(() => {
  'use strict';
  const statusNames={'needs-new':'需要新制','adapt-existing':'适配现有','reusable-after-review':'复验后复用'};
  window.renderProductionAssets=(data,state,ui)=>{
    const ledger=data.productionAssets;
    if(!ledger)return '<section class="review-page"><h1>资产清单暂不可用</h1><p>请重新构建界面数据。</p></section>';
    const all=ledger.models,base=all.reduce((sum,x)=>sum+x.baseMeshCount,0),lod=all.reduce((sum,x)=>sum+x.baseMeshCount*x.lodLevels,0),animationCount=new Set([...ledger.rigs.flatMap(r=>r.animations.map(a=>r.id+':'+a)),...all.filter(m=>!m.rigFamily).flatMap(m=>m.animations.map(a=>m.id+':'+a))]).size;
    const categories=[...new Set(all.map(x=>x.category))],category=state.assetCategory||'全部',phase=state.assetPhase||'全部';
    const selected=all.filter(x=>(category==='全部'||x.category===category)&&(phase==='全部'||x.phase===phase));
    const showArt=state.assetTab==='art';
    return `<section class="review-page production-ledger"><header><div><p class="context-label">制作需求 · 可逐项追踪</p><h1>一艘船之外，还有整个海上世界</h1><p>正式游戏的基础模型、复用关系与页面美术分别计数。清单表达制作预算，现有文件和可交付状态逐项列明。</p></div><div class="toolbar"><a class="button" href="../production-assets.md">83基模预算</a><a class="button primary" href="../../../production/resource-library/index.html">全游戏原画资源库</a></div></header><dl class="production-counts"><div><dt>独立基础模型</dt><dd>${base}<small>单人必需 ${all.filter(x=>x.phase!=='P2').length} · 可选 ${all.filter(x=>x.phase==='P2').length}</small></dd></div><div><dt>目标LOD交付</dt><dd>${lod}<small>不同距离的细节档位</small></dd></div><div><dt>共享人物骨架</dt><dd>${ledger.rigs.length}<small>成人与儿童分别管理</small></dd></div><div><dt>去重动作片段</dt><dd>${animationCount}<small>人物与门箱动作库</small></dd></div></dl><nav class="tabs" aria-label="资产类型">${ui.action('set','3D模型与动画',`tab ${!showArt?'active':''}`,{key:'assetTab',value:'models'})}${ui.action('set','本轮UI专用美术',`tab ${showArt?'active':''}`,{key:'assetTab',value:'art'})}</nav>${showArt?renderArt(data,ui):`<div class="asset-filter-bar"><div class="toolbar">${['全部',...categories].map(x=>ui.action('set',x,`button quiet ${category===x?'selected':''}`,{key:'assetCategory',value:x})).join('')}</div><div class="toolbar">${['全部','P0','P1','P2'].map(x=>ui.action('set',x,`button ${phase===x?'selected':''}`,{key:'assetPhase',value:x})).join('')}</div></div><p class="asset-result-count">显示 ${selected.length} / ${all.length} 个基础模型。P0：核心循环；P1：六幕补全；P2：可选陈设。颜色、实例与LOD不重复算作新基模。</p><div class="asset-table-wrap"><table class="asset-table"><thead><tr><th>基础模型</th><th>制作判断</th><th>阶段 / LOD</th><th>现有资源证据</th><th>对应页面</th></tr></thead><tbody>${selected.map(m=>`<tr><td><strong>${ui.e(m.name)}</strong><small>${ui.e(m.id)} · ${ui.e(m.category)}</small><p>${ui.e(m.notes.join(' '))}</p></td><td>${ui.pill(statusNames[m.productionStatus]||m.productionStatus)}${m.rigFamily?`<p class="small muted">骨架：${ui.e(m.rigFamily)}</p>`:''}<small>${m.variants.length} 个配置标签</small></td><td>${ui.pill(m.phase)}<p>${m.lodLevels} 档</p></td><td>${m.existing.length?m.existing.map(e=>`<a class="asset-source" href="../../../../${ui.e(e.path)}">${ui.e(e.path.split('/').pop())}</a><p>${ui.e(e.note)}</p>`).join(''):'需要制作新资产'}</td><td><div class="page-links">${m.pages.map(id=>`<a href="#${id}">${ui.e(data.screenGroups.flatMap(g=>g.screens).find(s=>s.id===id)?.title||id)}</a>`).join('')}</div></td></tr>`).join('')}</tbody></table></div><section class="production-notes"><h2>怎样避免把数量算大</h2><ol>${ledger.countingRules.map(x=>`<li>${ui.e(x)}</li>`).join('')}</ol></section>`}</section>`;
  };
  function renderArt(data,ui){
    const entries=data.artCatalog?.assets||[];
    return `<p class="asset-result-count">本轮采用 ${entries.length} 份专用美术。可点击原图检查；图像是界面资产，不计作3D模型。原始提示词和生成原件保留在采用记录中。</p><div class="art-direction-grid">${entries.map(x=>`<article><a href="${ui.e(x.path)}"><div class="art-stage ${x.transparent?'cutout':''}"><img loading="lazy" src="${ui.e(x.path)}" alt="${ui.e(x.name)}"></div></a><h2>${ui.e(x.name)}</h2><p>${ui.e(x.review)}</p><div class="page-links">${x.pages.map(id=>`<a href="#${id}">${ui.e(data.screenGroups.flatMap(g=>g.screens).find(s=>s.id===id)?.title||id)}</a>`).join('')}</div></article>`).join('')}</div>`;
  }
})();
